package com.cretas.aims.blueprint.draftentry;
import com.cretas.aims.entity.criticalcontroldraft.CriticalControlDraft; import com.cretas.aims.entity.qualityreleasedraft.QualityReleaseTemplateDraft; import com.cretas.aims.repository.criticalcontroldraft.CriticalControlDraftRepository; import com.cretas.aims.repository.qualityreleasedraft.QualityReleaseTemplateDraftRepository; import com.cretas.aims.service.criticalcontroldraft.CriticalControlDraftModels; import com.cretas.aims.service.deviationcapadraft.DeviationCapaTemplateDraftCommand; import com.cretas.aims.service.deviationcapadraft.DeviationCapaTemplateDraftModels.*; import com.cretas.aims.service.qualityreleasedraft.QualityReleaseTemplateDraftModels; import org.springframework.data.domain.*; import org.springframework.stereotype.Component; import java.util.*;
@org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name = "cretas.platform.factory-assembly.enabled", havingValue = "true", matchIfMissing = false)
@Component public class DeviationCapaDraftProposer implements CapabilityDraftProposer { private static final String WHY="蓝图没有偏差来源、触发、时限、根因、纠正和有效性复核的完整事实"; private static <E extends Enum<E>> List<Option> opts(Class<E> c){return Arrays.stream(c.getEnumConstants()).map(e->new Option(e.name(),e.name())).toList();} private static <E extends Enum<E>> String ec(Class<E> c){return Arrays.stream(c.getEnumConstants()).map(Enum::name).collect(java.util.stream.Collectors.joining("、"))+" 之一";} private static List<RequiredInput> policyFields(){return List.of(RequiredInput.integer("deviationSlaHours","偏差时限",WHY,"1–8760",1,8760),RequiredInput.integer("nonConformanceSlaHours","不符合时限",WHY,"1–8760",1,8760),RequiredInput.integer("capaSlaHours","CAPA时限",WHY,"1–8760",1,8760),RequiredInput.oneOf("rootCauseMethod","根因方法",WHY,ec(RootCauseMethod.class),opts(RootCauseMethod.class)),RequiredInput.integer("capaEffectivenessReviewDays","有效性复核天数",WHY,"1–3650",1,3650),RequiredInput.integer("recordRetentionDays","保留天数",WHY,"1–3650",1,3650),RequiredInput.text("changeReason","变更原因",WHY,"1–500 字",500));} private static List<RequiredInput> fields(){return List.of(RequiredInput.oneOf("sourceType","来源类型",WHY,ec(SourceType.class),opts(SourceType.class)),RequiredInput.text("sourceItemId","来源项目",WHY,"最长 128 位",128),RequiredInput.oneOf("triggerMode","触发模式",WHY,ec(TriggerMode.class),opts(TriggerMode.class)),RequiredInput.integer("repeatThreshold","重复阈值",WHY,"1–1000",1,1000),RequiredInput.integer("recurrenceWindowDays","复发窗口",WHY,"1–3650",1,3650),RequiredInput.values("authorityCodes","法规依据",WHY,"至少 1 项","依据",1,20,RequiredInput.text("authority","依据",WHY,"最长 128 位",128)),RequiredInput.text("changeReason","变更原因",WHY,"1–500 字",500));} private final CriticalControlDraftRepository controls; private final QualityReleaseTemplateDraftRepository releases; public DeviationCapaDraftProposer(CriticalControlDraftRepository controls,QualityReleaseTemplateDraftRepository releases){this.controls=controls;this.releases=releases;} public String capabilityId(){return DeviationCapaTemplateDraftCommand.CAPABILITY_ID;} public Proposed propose(Source s){var c=controls.findAll(Example.of(new CriticalControlDraft()),Sort.by(Sort.Direction.DESC,"createdAt")).stream().filter(x->s.factoryId().equals(x.getFactoryId())&&s.blueprint().getId().equals(x.getBlueprintId())&&Objects.equals(s.blueprint().getVersion().longValue(),x.getBlueprintVersion())&&s.sourceDigest().equals(x.getSourceDigest())&&"DRAFT".equals(x.getStatus())&&x.getDesiredDigest()!=null&&x.getDesiredDigest().matches("[0-9a-f]{64}")).findFirst().orElse(null);var q=releases.findAll(Example.of(new QualityReleaseTemplateDraft()),Sort.by(Sort.Direction.DESC,"createdAt")).stream().filter(x->s.factoryId().equals(x.getFactoryId())&&s.blueprint().getId().equals(x.getBlueprintId())&&Objects.equals(s.blueprint().getVersion().longValue(),x.getBlueprintVersion())&&s.sourceDigest().equals(x.getSourceDigest())&&"DRAFT".equals(x.getStatus())&&x.getDesiredDigest()!=null&&x.getDesiredDigest().matches("[0-9a-f]{64}")).findFirst().orElse(null);if(c==null||q==null)return Proposed.blocked("UPSTREAM_MISSING","偏差 CAPA 必须绑定同蓝图关键控制和质量放行草稿","先完成关键控制和质量放行草稿");var req=new DraftRequest(s.factoryId(),s.blueprint().getId(),s.blueprint().getVersion(),s.sourceDigest(),new CriticalControlPin(c.getId(),c.getDesiredDigest()),new QualityReleasePin(q.getId(),q.getDesiredDigest()),List.of(),null,null,null,0);return Proposed.single(capabilityId(),"偏差 CAPA 模板",req,List.of(RequiredInput.object("policy","CAPA策略",WHY,"完整填写",policyFields()),RequiredInput.list("rules","偏差规则",WHY,"至少 1 条","规则",1,200,fields())),List.of(new Evidence("criticalControl",c.getId()+" / "+c.getDesiredDigest()),new Evidence("qualityRelease",q.getId()+" / "+q.getDesiredDigest())));}}
